[[maybe_unused]] static std::string weatherLabel(int c){if(!state.language)return weatherName(c);if(c==0)return "Clear";if(c<=3)return "Cloudy";if(c==45||c==48)return "Fog";if(c>=51&&c<=67)return "Rain";if(c>=71&&c<=77)return "Snow";if(c>=80&&c<=82)return "Showers";if(c==85||c==86)return "Snow showers";if(c>=95)return "Thunderstorm";return "Weather";}
