static std::vector<int> hoursForDay(int d){std::vector<int> out;if(d<0||d>=(int)viewWeather().dates.size())return out;auto it=hourly().find("time");if(it==hourly().end()||!it->is_array())return out;for(size_t i=0;i<it->size()&&i<300;++i){std::string stamp=(*it)[i];if(stamp.substr(0,10)==viewWeather().dates[d])out.push_back(i);}if(!out.empty()){int next=out.back()+1;if(next<(int)it->size()&&(*it)[next].get<std::string>().substr(11,5)=="00:00")out.push_back(next);}return out;}
