static std::vector<std::string> zonesFor(const std::string& code){auto it=timeZones.find("countries");if(it==timeZones.end()||!it->contains(code))return {};return (*it)[code].get<std::vector<std::string>>();}
static std::string zoneFor(const Country& c){auto zones=zonesFor(c.code);if(!c.zone.empty()&&std::find(zones.begin(),zones.end(),c.zone)!=zones.end())return c.zone;return defaultZone(c.code,zones);}
static std::string zoneCity(std::string zone){auto pos=zone.rfind('/');if(pos!=std::string::npos)zone=zone.substr(pos+1);std::replace(zone.begin(),zone.end(),'_',' ');return zone;}
static std::string cityName(const Location& l){auto cached=l.names.find(languageInfo(state.language).code);if(cached!=l.names.end()&&!cached->second.empty())return cached->second;const std::string& translated=state.language?l.cityEn:l.cityRu;if(!translated.empty()&&(state.language==0||state.language==1||state.language==18))return translated;auto it=cityNames.find(l.zone);if(it!=cityNames.end()&&(l.city.empty()||l.city==zoneCity(l.zone)||l.city==it->value("ru",std::string{})||l.city==it->value("en",std::string{})))return localeName(state.language,"cities",l.zone,it->value(state.language?"en":"ru",l.city));return translated.empty()?l.city:translated;}
static std::string countryCity(const Country& c){for(const auto& place:state.regions)if(place.location.country==c.code&&place.location.zone==zoneFor(c)&&(c.clockCity.empty()||c.clockCity==place.location.city))return cityName(place.location);Location l;l.zone=zoneFor(c);l.city=c.clockCity;return cityName(l);}
static SceDateTime countryClock(const Country& c){return clockAt(zoneOffset(zoneRules(),zoneFor(c),utcNow()));}
static std::vector<Country> trackedClocks(){std::vector<Country> out;for(const auto& c:state.countries)if(c.clock){bool rootFound=false;for(const auto& place:state.regions)if(countryPlace(c,place.location)||(place.origin==3&&place.location.country==c.code)){rootFound|=countryPlace(c,place.location);if(place.clock){auto city=c;city.zone=place.location.zone;city.clockCity=place.location.city;city.cityPinned=true;city.cityLat=place.location.lat;city.cityLon=place.location.lon;out.push_back(city);}}if(c.cityEnabled&&!rootFound)out.push_back(c);}return out;}

static WeatherNow currentWeather(const Location& location,const Weather& weather,long long updated){auto n=clockAt(zoneOffset(zoneRules(),location.zone,utcNow(),location.offset));return weatherNow(weather,{n.year,n.month,n.day},n.hour,freshObservation(updated,utcNow(),wifiConnected));}
static long long viewUpdated(){return weatherRegion>=0&&weatherRegion<(int)state.regions.size()?state.regions[weatherRegion].updated:state.updated;}
static ForecastAge weatherAge(const Location& location,const Weather& weather,long long updated){auto n=clockAt(zoneOffset(zoneRules(),location.zone,utcNow(),location.offset));return forecastAge(weather,updated,utcNow(),wifiConnected,{n.year,n.month,n.day},n.hour);}
static std::string savedTime(long long updated,bool includeDate=false){
    const auto& location=state.location;
    time_t epoch=updated+zoneOffset(zoneRules(),location.zone,updated,location.offset);tm d{};gmtime_r(&epoch,&d);Date date{d.tm_year+1900,d.tm_mon+1,d.tm_mday};auto n=clockAt(zoneOffset(zoneRules(),location.zone,utcNow(),location.offset));
    return (!includeDate&&key(date)==key({n.year,n.month,n.day})?"":shortDate(date)+" · ")+clockTime(d.tm_hour,d.tm_min,state.time24);
}
static bool updateWasYesterday(long long updated){auto& location=state.location;time_t epoch=updated+zoneOffset(zoneRules(),location.zone,updated,location.offset);tm d{};gmtime_r(&epoch,&d);auto n=clockAt(zoneOffset(zoneRules(),location.zone,utcNow(),location.offset));return key({d.tm_year+1900,d.tm_mon+1,d.tm_mday})==key(shift({n.year,n.month,n.day},-1));}
static std::string weatherAgeText(const Location& location,const Weather& weather,long long updated){
    auto age=weatherAge(location,weather,updated);std::string label;
    if(age.status==ForecastFreshness::Missing)return t("Прогноз ещё не загружен","Forecast has not loaded yet");
    if(age.status==ForecastFreshness::Expired)label=t("Сохранённый прогноз закончился","Saved forecast expired");
    else if(age.status==ForecastFreshness::Cached&&(!wifiConnected||!age.known))label=t("Сохранённый прогноз","Saved forecast");
    else return updatedRelative(age.seconds,state.language,age.known&&updateWasYesterday(updated));
    return label+" · "+(age.known?relativeAge(age.seconds,state.language,updateWasYesterday(updated)):t("Время обновления неизвестно","Update time unknown"));
}
static unsigned weatherAgeColor(const ForecastAge& age){return age.status==ForecastFreshness::Expired?colors[9]:age.status==ForecastFreshness::Cached?RGBA8(215,153,65,255):p.muted;}
static std::string currentTemperature(const WeatherNow& weather,int units){if(!weather.valid)return "—";if(weather.hourly)return valueIn(weather.temperature,0,units);return numeric(temperature(weather.low,units))+" / "+numeric(temperature(weather.high,units))+(units?"°F":"°C");}
