static std::string observanceKey(const Holiday& h){auto k=holidayNameKey(h.english.empty()?localizedHolidayTitle(h,1):h.english);if(k=="christmas"||k=="christmas day"||k=="orthodox christmas day")return "christmas";if(k=="new year"||k=="new year's day"||k=="new year’s day")return "new year";return k;}
