static double analogAxis(int value){double v=(value-128)/127.;return std::abs(v)<.15?0:std::copysign((std::abs(v)-.15)/.85,v);}
static void pickerAnalog(int lx,int ly,int rx,int ry,double dt){dt=std::clamp(dt,0.,.05);picker.s=std::clamp(picker.s+analogAxis(lx)*dt*.65,0.,1.);picker.v=std::clamp(picker.v-analogAxis(ly)*dt*.65,0.,1.);double hue=std::abs(ry-128)>=std::abs(rx-128)?analogAxis(ry):analogAxis(rx);picker.h=fmod(picker.h+hue*dt*150.+360.,360.);}
