static void moveHome(unsigned b){if(homeBlock>=0&&b&(SCE_CTRL_LEFT|SCE_CTRL_RIGHT|SCE_CTRL_UP|SCE_CTRL_DOWN)){homeFocus=homeBlock==0?(trackedClocks().empty()?0:clockScroll+1):homeBlock==1?101:200;if(homeBlock==1)selected.d=1;homeBlock=-1;return;}if(homeFocus>=1&&homeFocus<=16){int slot=homeFocus-1-clockScroll,count=trackedClocks().size();if((b&SCE_CTRL_RIGHT)&&slot%4==3&&clockScroll+8<count){changeClockPage(1,slot/4*4);return;}if((b&SCE_CTRL_LEFT)&&slot%4==0&&clockScroll>0){changeClockPage(-1,slot/4*4+3);return;}}auto targets=homeTargets();auto current=std::find_if(targets.begin(),targets.end(),[&](const HomeTarget& t){return t.id==homeFocus;});if(current==targets.end()){homeFocus=200;return;}int dx=b&SCE_CTRL_LEFT?-1:b&SCE_CTRL_RIGHT?1:0,dy=b&SCE_CTRL_UP?-1:b&SCE_CTRL_DOWN?1:0;if(!dx&&!dy)return;double best=1e9;int chosen=homeFocus;for(const auto& t:targets){int x=t.x-current->x,y=t.y-current->y,along=dx?x*dx:y*dy,across=dx?abs(y):abs(x);if(along<=0)continue;double score=along+across*2.5;if(score<best){best=score;chosen=t.id;}}if(chosen==80||chosen==81){changeClockPage(chosen==80?-1:1);return;}homeFocus=chosen;if(homeFocus>=101&&homeFocus<=131)selected.d=homeFocus-100;}
