 std::string confirm=circleEnter?"circle":"cross",back=circleEnter?"cross":"circle";
 auto choose=ControlHint{confirm,t("Выбрать","Select")},leave=ControlHint{back,t("Назад","Back")},move=ControlHint{"dpad",t("Навигация","Navigate")},tabs=ControlHint{"shoulders",t("Вкладки","Tabs")};
