 if((page==1&&calendarReader)||(page==2&&settingsTab==13))return {{"left-stick",t("Прокрутка","Scroll")},move,leave,tabs};
 if((page==0||page==3)&&weatherDay>=0)return {{"dpad",t("Показатель / минута","Metric / minute")},{"right-stick",t("Курсор","Cursor")},{"square",t("Предыдущий день","Previous day")},{"triangle",t("Следующий день","Next day")},leave};
