 if(page==1)return {move,choose,{"right-stick",t("Месяц","Month")},{"triangle",t("Весь текст","Full text")},leave,tabs};
 if(page==3)return {move,choose,{"triangle",t("Поиск города","Search cities")},{"square",t("Обновить","Refresh")},leave,tabs};
